/**
 * The canonical room taxonomy — the same seven rooms in every palace.
 *
 * Why fixed: a map you have to relearn per project is not a map. Walking into
 * any repo, `architecture` means the same thing, sits in the same place, and
 * answers the same question. Muscle memory is the point.
 *
 * How it is enforced: MemPalace routes a mined file into a room by matching
 * room keywords against the file's path. Verified empirically — a file at
 * `.palace/decisions/adr-002-tests-harness-choice.md` routes to `decisions`,
 * not `tests`, even though its *filename* contains another room's keyword.
 * The containing directory wins. So the directory layout IS the schema, and
 * each room carries exactly one keyword: its own name. Adding synonyms would
 * reintroduce the ambiguity this design exists to remove.
 *
 * `inbox` is last and carries no keywords. In MemPalace a keyword-less room is
 * the fallback bucket, so anything that fails to match a canonical room lands
 * there — visible, never silently dropped, and never canonical.
 */
export const ROOMS = [
    {
        name: "architecture",
        description: "Structure, boundaries, layers",
        answers: "How is this system put together, and where are its seams?",
        keywords: ["architecture"],
    },
    {
        name: "decisions",
        description: "ADRs, tradeoffs, why-not",
        answers: "Why is it this way, and what did we reject?",
        keywords: ["decisions"],
    },
    {
        name: "docs",
        description: "Usage, setup, API",
        answers: "How do I use it?",
        keywords: ["docs"],
    },
    {
        name: "tests",
        description: "Test strategy, fixtures, known gaps",
        answers: "What is verified, how, and what is not?",
        keywords: ["tests"],
    },
    {
        name: "runbooks",
        description: "Deploy, debug, oncall",
        answers: "It is broken at 3am — what do I do?",
        keywords: ["runbooks"],
    },
    {
        name: "glossary",
        description: "Domain language",
        answers: "What does this word mean here?",
        keywords: ["glossary"],
    },
    {
        name: "inbox",
        description: "Unfiled — never canonical",
        answers: "Worth keeping, not yet placed. Empty this regularly.",
        keywords: [],
    },
];
export const ROOM_NAMES = ROOMS.map((r) => r.name);
/** The one room that is allowed to be untrustworthy. */
export const INBOX = "inbox";
/** Rooms that constitute the actual map. Content here is expected to be correct. */
export const CANONICAL_ROOMS = ROOM_NAMES.filter((n) => n !== INBOX);
export function isRoom(name) {
    return ROOM_NAMES.includes(name);
}
/**
 * Render `.palace/mempalace.yaml`.
 *
 * Hand-written rather than produced by a YAML library on purpose: this file is
 * generated, compared, and repaired by exact string equality. `palace doctor`
 * regenerates it from the wing name and diffs — any drift, including a
 * well-meaning hand edit that adds a room, is reported rather than silently
 * absorbed. That is only sound if rendering is byte-stable.
 */
export function renderConfig(wing) {
    const lines = [
        "# Generated by `palace init` — do not edit by hand.",
        "# `palace doctor` regenerates this and reports any drift.",
        `wing: ${wing}`,
        "rooms:",
    ];
    for (const room of ROOMS) {
        lines.push(`- name: ${room.name}`);
        lines.push(`  description: ${room.description}`);
        const kw = room.keywords.length ? `[${room.keywords.join(", ")}]` : "[]";
        lines.push(`  keywords: ${kw}`);
    }
    return lines.join("\n") + "\n";
}
/**
 * Extract the wing from a rendered config without a YAML parser.
 * Returns null if the file does not carry a recognizable wing line.
 */
export function readWing(configText) {
    const match = configText.match(/^wing:[ \t]*(\S+)[ \t]*$/m);
    return match?.[1] ?? null;
}
/**
 * Placeholder that lets git track an empty room.
 *
 * Deliberately not a README.md. Anything with a document extension inside a room
 * gets mined, and scaffolding text like "file a note here" then comes back as a
 * search hit — measured: a room README ranked first for its own boilerplate.
 * Room documentation belongs in `palace help` and the project docs, never inside
 * the index it would pollute.
 */
export const ROOM_PLACEHOLDER = ".gitkeep";
